(() => {
  'use strict';
  const status = document.getElementById('callback-status');
  const input = document.getElementById('callback-url');
  const button = document.getElementById('copy-callback');
  const notice = document.getElementById('copy-status');
  const url = new URL(window.location.href);
  const values = url.searchParams;
  const codes = values.getAll('code');
  const states = values.getAll('state');
  const valid = !values.has('error') && codes.length === 1 && states.length === 1 &&
    codes[0].length > 0 && codes[0].length <= 4096 && states[0].length > 0 && states[0].length <= 512 &&
    [...values.keys()].every(key => ['code', 'state'].includes(key));
  if (!valid) {
    status.textContent = values.has('error') ? 'Bufferでの許可が完了していません。アプリのBuffer接続からやり直してください。' :
      '接続用の情報がありません。先にアプリでBuffer接続を開始してください。';
    input.hidden = true;
    return;
  }
  // Keep the code in this page only. The desktop app validates state and PKCE.
  let callback = url.origin + url.pathname + url.search;
  input.value = callback;
  button.disabled = false;
  status.textContent = 'Bufferから接続用の情報を受け取りました。アプリへ貼り付けると確認が完了します。';
  history.replaceState(null, '', url.pathname);
  button.addEventListener('click', async () => {
    try {
      await navigator.clipboard.writeText(callback);
      notice.textContent = 'コピーしました。アプリのBuffer接続画面へ貼り付けてください。';
    } catch {
      input.focus(); input.select();
      notice.textContent = '自動コピーが許可されませんでした。選択されたURLをコピーして、アプリへ貼り付けてください。';
    }
  });
  window.addEventListener('pagehide', () => { callback = ''; input.value = ''; });
})();
